-- 老板中世纪收藏卡。可重复执行。
UPDATE `cards` SET `description` = '立即造成 5 点伤害，双方各获得 2 点防御', `card_type` = 'attack', `cost` = 3 WHERE `card_code` = 'B-01';
DELETE e FROM `card_effects` e INNER JOIN `cards` c ON c.id = e.card_id WHERE c.card_code = 'B-01';

UPDATE `cards` SET `description` = '双方各获得 2 点防御，并各恢复 1 点血量', `card_type` = 'defend', `cost` = 2 WHERE `card_code` = 'B-02';
DELETE e FROM `card_effects` e INNER JOIN `cards` c ON c.id = e.card_id WHERE c.card_code = 'B-02';

UPDATE `cards` SET `description` = '立即造成 2 点伤害，抽 1 张牌，本回合员工调用机会 +1', `card_type` = 'support', `cost` = 1 WHERE `card_code` = 'B-03';
DELETE e FROM `card_effects` e INNER JOIN `cards` c ON c.id = e.card_id WHERE c.card_code = 'B-03';

ALTER TABLE `cards` AUTO_INCREMENT = 154;
